#!/usr/bin/env node
// Builds the block registries from the folders in src/blocks.
//
//   node scripts/generate-blocks.mjs          write the generated files
//   node scripts/generate-blocks.mjs --check  fail if they are out of date (used by tests and CI)
//
// A block is a folder with block.ts, render.ts and View.svelte. Editor.svelte and style.css are
// optional. See src/blocks/kit.ts for the contract. The scripts and the output use plain ASCII.
import { existsSync, readFileSync, readdirSync, statSync, writeFileSync } from 'node:fs';
import { dirname, join } from 'node:path';
import { fileURLToPath } from 'node:url';

const root = join(dirname(fileURLToPath(import.meta.url)), '..', 'src', 'blocks');
const HEADER =
  '// Generated by scripts/generate-blocks.mjs from the folders in this directory.\n// Do not edit by hand: add or remove a block folder and run `pnpm blocks:generate`.\n';

export function discover(dir = root) {
  const names = readdirSync(dir)
    .filter((name) => statSync(join(dir, name)).isDirectory())
    .filter((name) => existsSync(join(dir, name, 'block.ts')))
    .sort();
  for (const name of names) {
    if (!/^[a-z][a-z0-9-]*$/.test(name))
      throw new Error(`Block folder "${name}" must be lower-case letters, digits and hyphens.`);
    for (const required of ['render.ts', 'View.svelte'])
      if (!existsSync(join(dir, name, required)))
        throw new Error(`Block "${name}" is missing ${required}.`);
  }
  return names.map((name) => ({
    name,
    id: name.replace(/-([a-z0-9])/g, (_, c) => c.toUpperCase()),
    editor: existsSync(join(dir, name, 'Editor.svelte')),
    style: existsSync(join(dir, name, 'style.css'))
  }));
}

export function render(blocks) {
  const imports = (file) =>
    blocks.map((b) => `import ${b.id} from './${b.name}/${file}';`).join('\n');
  const authoring =
    HEADER +
    (blocks.length ? imports('block') + '\n' : '') +
    `\nexport const blockModules = [${blocks.map((b) => b.id).join(', ')}] as const;\n` +
    `export const blockDefinitions = blockModules.map((block) => block.definition);\n` +
    `export const blockExtensions = blockModules.map((block) => block.extension);\n`;
  const reader =
    HEADER +
    '// Only host-reviewed local components can activate. Stored module URLs are never imported.\n' +
    (blocks.length ? imports('render') + '\n' : '') +
    `\nexport const implementations = {\n` +
    blocks.map((b) => `  [${b.id}.module]: () => import('./${b.name}/View.svelte'),\n`).join('') +
    `};\nexport const rendererRegistry = {\n` +
    blocks.map((b) => `  [${b.id}.type]: ${b.id}.entry,\n`).join('') +
    `};\n`;
  const withEditor = blocks.filter((b) => b.editor);
  const editors =
    HEADER +
    `import type { Component } from 'svelte';\nimport type { EditorProps } from './kit';\n` +
    (withEditor.length
      ? imports('render')
          .split('\n')
          .filter((l) => withEditor.some((b) => l.includes(` ${b.id} `)))
          .join('\n') + '\n'
      : '') +
    `\n// Blocks without an Editor.svelte get a form generated from their payload schema.\n` +
    `export const editors: Partial<
  Record<string, () => Promise<{ default: Component<EditorProps> }>>
> = {\n` +
    withEditor
      .map((b) => `  [${b.id}.type]: () => import('./${b.name}/Editor.svelte'),\n`)
      .join('') +
    `};\n`;
  const styles =
    '/* Generated by scripts/generate-blocks.mjs. Do not edit by hand. */\n' +
    blocks
      .filter((b) => b.style)
      .map((b) => `@import './${b.name}/style.css';\n`)
      .join('');
  return {
    'authoring.ts': authoring,
    'reader.ts': reader,
    'editors.ts': editors,
    'styles.css': styles
  };
}

export function generate({ check = false, dir = root } = {}) {
  const files = render(discover(dir));
  const stale = [];
  for (const [name, content] of Object.entries(files)) {
    const path = join(dir, name);
    const current = existsSync(path) ? readFileSync(path, 'utf8') : null;
    if (current === content) continue;
    stale.push(name);
    if (!check) writeFileSync(path, content);
  }
  return stale;
}

if (process.argv[1] && fileURLToPath(import.meta.url) === process.argv[1]) {
  const check = process.argv.includes('--check');
  const stale = generate({ check });
  if (check && stale.length) {
    console.error(`Out of date: ${stale.join(', ')}. Run \`pnpm blocks:generate\`.`);
    process.exit(1);
  }
  console.log(stale.length ? `Updated ${stale.join(', ')}` : 'Block registries are up to date');
}
